from abc import ABCMeta, abstractproperty


class SicMessage(object):

    __metaclass__ = ABCMeta

    def __init__(self, *attributes):
        self.attributes = attributes

    @abstractproperty
    def id(self):
        """SicMessage type id"""

    @property
    def payload(self):
        """Get serialized attributes."""
        return self.attributes


class ApiAlarmMsg(SicMessage):

    id = 0x2B84

    def __init__(self, fault_id, unit_id, *fault_params):
        SicMessage.__init__(self, fault_id, unit_id, 4 * len(fault_params), *fault_params)


class Api2AlarmMsg(SicMessage):

    id = 0x137C

    def __init__(self, fault_state, fault_id, unit_id, *fault_params):
        SicMessage.__init__(self, fault_state, fault_id, unit_id, 4 * len(fault_params), *fault_params)


class ApiSfpStatusIndMsg(SicMessage):

    id = 0x11DF

    number_of_statuses = 1

    def __init__(self, board_id, sfp_connector_id, status_type, status):
        SicMessage.__init__(self, board_id, sfp_connector_id, self.number_of_statuses, status_type, status)


class LomFaultReportIndication(SicMessage):

    id = 0x35F0

    max_fault_params_count = 13

    def __init__(self, fault_id, state, severity, object_type, unit_id, *fault_params):
        fault_params = list(fault_params) + [0] * (self.max_fault_params_count - len(fault_params))
        SicMessage.__init__(self, fault_id, state, severity, object_type, unit_id, *fault_params)


